/** Same equirectangular projection used to build WORLD_MAP_PATH above —
 * callers place pins with this so they land in the right spot on the map. */
export function lonLatToXY(lon: number, lat: number): { x: number; y: number } {
  return {
    x: (lon + 180) * (WORLD_MAP_VIEW_WIDTH / 360),
    y: (90 - lat) * (WORLD_MAP_VIEW_HEIGHT / 180),
  };
}
